'use client';

import Link from 'next/link';
import { useCallback, useEffect, useMemo, useState, type FormEvent } from 'react';
import { Activity, ArrowLeftRight, ArrowUpRight, Banknote, BookOpen, Briefcase, CalendarDays, Check, Download, FileText, Gift, Heart, Landmark, Loader2, Pencil, Plus, Printer, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Target, Trash2, TrendingUp, Wallet } from 'lucide-react';
import { currentFinancialMonth, formatBasisPoints, formatMajorInput, formatMinor, parseMoneyToMinor, parsePercentToBasisPoints } from '@/lib/finance/money';

type Section = 'overview'|'income'|'allocation'|'transactions'|'budgets'|'savings'|'reports'|'settings';
type Row = Record<string, any>;
type Snapshot = { settings: Row; categories: Row[]; subcategories: Row[]; plans: Row[]; incomes: Row[]; runs: Row[]; allocations: Row[]; transactions: Row[]; goals: Row[]; investments: Row[]; adjustments: Row[]; projects: Row[]; learningExperiences: Row[]; summary: { summary: Row; budgets: Row[]; goals: Row[]; investments: Row[]; trends: Row[]; recentTransactions: Row[] } };
type IncomeDraft = { title:string; amount:string; currency:string; source:string; receivedAt:string; description:string; paymentMethod:string; attachmentLabel:string; attachmentUrl:string; status:'EXPECTED'|'RECEIVED'|'CANCELLED'; changeNote:string };
type TransactionDraft = { title:string; amount:string; currency:string; transactionType:string; categoryKey:string; transferToCategoryKey:string; subcategoryId:string; transactionDate:string; paymentMethod:string; description:string; attachmentLabel:string; attachmentUrl:string; goalId:string; investmentId:string; projectId:string; learningExperienceId:string };

const NAV: {key:Section;label:string;href:string;icon:any}[] = [
  {key:'overview',label:'Overview',href:'/admin/finance',icon:Wallet}, {key:'income',label:'Income',href:'/admin/finance/income',icon:Banknote}, {key:'allocation',label:'Allocation',href:'/admin/finance/allocation',icon:ArrowLeftRight}, {key:'transactions',label:'Transactions',href:'/admin/finance/transactions',icon:Activity}, {key:'budgets',label:'Budgets',href:'/admin/finance/budgets',icon:TrendingUp}, {key:'savings',label:'Savings & Investments',href:'/admin/finance/savings',icon:Landmark}, {key:'reports',label:'Reports',href:'/admin/finance/reports',icon:FileText}, {key:'settings',label:'Settings',href:'/admin/finance/settings',icon:Settings2},
];
const CURRENCY_CHOICES=['ETB','USD','EUR','GBP','KES','CAD','AUD','JPY','KWD','AED','SAR'];
const TODAY=()=>new Date().toISOString().slice(0,10);
const MONTH=()=>currentFinancialMonth(new Date(),1);
const blankIncome=(currency='ETB'):IncomeDraft=>({title:'',amount:'',currency,source:'Freelance development',receivedAt:TODAY(),description:'',paymentMethod:'',attachmentLabel:'',attachmentUrl:'',status:'EXPECTED',changeNote:''});
const blankTransaction=(currency='ETB'):TransactionDraft=>({title:'',amount:'',currency,transactionType:'EXPENSE',categoryKey:'ESSENTIAL',transferToCategoryKey:'BUSINESS',subcategoryId:'',transactionDate:TODAY(),paymentMethod:'',description:'',attachmentLabel:'',attachmentUrl:'',goalId:'',investmentId:'',projectId:'',learningExperienceId:''});
const moneyInput=(value:string,currency:string)=>parseMoneyToMinor(value,currency);
const shareWidth=(value:string,total:string)=>{const whole=BigInt(total);return pctWidth(whole>BigInt(0)?Number((BigInt(value)*BigInt(10000))/whole):0)};
const pctWidth=(basisPoints:number)=>`${Math.max(0,Math.min(100, basisPoints/100))}%`;

export default function PersonalFinanceWorkspace({section='overview'}:{section?:Section}) {
  const [data,setData]=useState<Snapshot|null>(null); const [loading,setLoading]=useState(true); const [error,setError]=useState(''); const [message,setMessage]=useState('');
  const [currency,setCurrency]=useState(''); const [month,setMonth]=useState(MONTH()); const [monthTouched,setMonthTouched]=useState(false); const [query,setQuery]=useState(''); const [statusFilter,setStatusFilter]=useState('ALL');
  const [editingIncome,setEditingIncome]=useState<number|null>(null); const [incomeForm,setIncomeForm]=useState<IncomeDraft>(blankIncome());
  const [editingTransaction,setEditingTransaction]=useState<number|null>(null); const [transactionForm,setTransactionForm]=useState<TransactionDraft>(blankTransaction());
  const [goalForm,setGoalForm]=useState({goalType:'GOAL',title:'',target:'',currency:'ETB',deadline:'',notes:''}); const [editingGoalId,setEditingGoalId]=useState<number|null>(null);
  const [investmentForm,setInvestmentForm]=useState({name:'',investmentCategory:'Diversified investment fund',currency:'ETB',currentValue:'',valueAsOf:TODAY(),notes:''}); const [editingInvestmentId,setEditingInvestmentId]=useState<number|null>(null);
  const [question,setQuestion]=useState('Summarize this period and highlight one practical budgeting improvement.'); const [insight,setInsight]=useState(''); const [aiBusy,setAiBusy]=useState(false);
  const [planForm,setPlanForm]=useState({effectiveDate:TODAY(),giving:'10',essential:'30',business:'30',emergency:'15',investment:'10',learning:'10',enjoyment:'5',explanation:''}); const [planInitialized,setPlanInitialized]=useState(false);
  const [adjustment,setAdjustment]=useState({categoryKey:'ESSENTIAL',amount:'',effectiveDate:TODAY(),explanation:''});
  const [categoryName,setCategoryName]=useState(''); const [categoryDescription,setCategoryDescription]=useState(''); const [subCategory,setSubCategory]=useState({categoryKey:'ESSENTIAL',name:''});
  const [reportData,setReportData]=useState<Row|null>(null); const [reportLoading,setReportLoading]=useState(false); const [reportPeriod,setReportPeriod]=useState('monthly'); const [reportQuarter,setReportQuarter]=useState(`${new Date().getUTCFullYear()}-Q${Math.ceil((new Date().getUTCMonth()+1)/3)}`); const [reportYear,setReportYear]=useState(String(new Date().getUTCFullYear()));
  const selectedCurrency=currency||data?.settings?.primaryCurrency||'ETB';

  const load=useCallback(async()=>{
    setLoading(true);setError('');
    try { const response=await fetch(`/api/admin/finance?currency=${encodeURIComponent(selectedCurrency)}&month=${encodeURIComponent(month)}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error||'Could not load finance records.');setData(body as Snapshot);if(!currency&&body.settings?.primaryCurrency)setCurrency(body.settings.primaryCurrency); }
    catch (cause) { setError(cause instanceof Error?cause.message:'Could not load finance records.'); }
    finally { setLoading(false); }
  },[selectedCurrency,month,currency]);
  useEffect(()=>{void load()},[load]);
  useEffect(()=>{if(data?.settings&&!monthTouched){const current=currentFinancialMonth(new Date(),data.settings.monthStartDay??1);if(current!==month)setMonth(current)}},[data,month,monthTouched]);
  useEffect(()=>{if(section!=='reports'||!data){setReportData(null);return}let alive=true;setReportLoading(true);const url=reportJsonHref(reportPeriod,month,reportQuarter,reportYear,selectedCurrency);fetch(url,{cache:'no-store'}).then(async response=>{const body=await response.json();if(!response.ok)throw new Error(body.error||'Could not load the selected finance report.');return body}).then(body=>{if(alive)setReportData(body)}).catch(cause=>{if(alive){setReportData(null);setError(cause instanceof Error?cause.message:'Could not load the selected finance report.')}}).finally(()=>{if(alive)setReportLoading(false)});return()=>{alive=false}},[section,Boolean(data),reportPeriod,month,reportQuarter,reportYear,selectedCurrency]);
  useEffect(()=>{if(data?.plans?.[0]&&!planInitialized){const p=data.plans[0];setPlanForm({effectiveDate:TODAY(),giving:(p.givingBp/100).toFixed(2).replace(/\.?0+$/,''),essential:(p.essentialBp/100).toFixed(2).replace(/\.?0+$/,''),business:(p.businessBp/100).toFixed(2).replace(/\.?0+$/,''),emergency:(p.emergencyBp/100).toFixed(2).replace(/\.?0+$/,''),investment:(p.investmentBp/100).toFixed(2).replace(/\.?0+$/,''),learning:(p.learningBp/100).toFixed(2).replace(/\.?0+$/,''),enjoyment:(p.enjoymentBp/100).toFixed(2).replace(/\.?0+$/,''),explanation:''});setPlanInitialized(true)}},[data,planInitialized]);
  const currencies=useMemo(()=>Array.from(new Set([data?.settings?.primaryCurrency??'ETB',...(data?.incomes??[]).map((row)=>row.currency),...(data?.transactions??[]).map((row)=>row.currency),...(data?.goals??[]).map((row)=>row.currency),...(data?.investments??[]).map((row)=>row.currency)])).sort(),[data]);
  const cats=(data?.categories??[]).filter((row)=>row.isActive);
  const summary=data?.summary?.summary;
  const allIncomes=(data?.incomes??[]).filter((row)=>row.currency===selectedCurrency).filter((row)=>statusFilter==='ALL'||row.status===statusFilter).filter((row)=>`${row.title} ${row.source} ${row.description??''}`.toLowerCase().includes(query.toLowerCase()));
  const allTransactions=(data?.transactions??[]).filter((row)=>row.currency===selectedCurrency).filter((row)=>`${row.title} ${row.transactionType} ${row.categoryKey??''} ${row.description??''}`.toLowerCase().includes(query.toLowerCase()));

  async function mutate(path:string,method:'POST'|'PATCH'|'DELETE',payload?:unknown){
    setMessage('');setError('');
    try {const response=await fetch(path,{method,headers:{'content-type':'application/json'},body:payload===undefined?undefined:JSON.stringify(payload)});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'The finance update could not be saved.');setMessage('Saved. Finance totals now reflect the stored records.');await load();return body;}
    catch(cause){setError(cause instanceof Error?cause.message:'The finance update could not be saved.');return null;}
  }
  const updateIncomeField=(key:keyof IncomeDraft,value:string)=>setIncomeForm((form)=>({...form,[key]:value}));
  const updateTransactionField=(key:keyof TransactionDraft,value:string)=>setTransactionForm((form)=>({...form,[key]:value}));

  function beginIncome(row?:Row){if(row){setEditingIncome(row.id);setIncomeForm({title:row.title,amount:majorAmount(row.amountMinor,row.currency),currency:row.currency,source:row.source,receivedAt:row.receivedAt,description:row.description??'',paymentMethod:row.paymentMethod??'',attachmentLabel:row.attachmentLabel??'',attachmentUrl:row.attachmentUrl??'',status:row.status,changeNote:''})}else{setEditingIncome(null);setIncomeForm(blankIncome(selectedCurrency))}}
  function beginTransaction(row?:Row){if(row){setEditingTransaction(row.id);setTransactionForm({title:row.title,amount:majorAmount(row.amountMinor,row.currency),currency:row.currency,transactionType:row.transactionType,categoryKey:row.categoryKey??'ESSENTIAL',transferToCategoryKey:row.transferToCategoryKey??'BUSINESS',subcategoryId:row.subcategoryId?String(row.subcategoryId):'',transactionDate:row.transactionDate,paymentMethod:row.paymentMethod??'',description:row.description??'',attachmentLabel:row.attachmentLabel??'',attachmentUrl:row.attachmentUrl??'',goalId:row.goalId?String(row.goalId):'',investmentId:row.investmentId?String(row.investmentId):'',projectId:row.projectId?String(row.projectId):'',learningExperienceId:row.learningExperienceId?String(row.learningExperienceId):''})}else{setEditingTransaction(null);setTransactionForm(blankTransaction(selectedCurrency))}}

  async function saveIncome(event:FormEvent){event.preventDefault();try{const payload={title:incomeForm.title,amountMinor:moneyInput(incomeForm.amount,incomeForm.currency),currency:incomeForm.currency.toUpperCase(),source:incomeForm.source,receivedAt:incomeForm.receivedAt,description:incomeForm.description||null,paymentMethod:incomeForm.paymentMethod||null,attachmentLabel:incomeForm.attachmentLabel||null,attachmentUrl:incomeForm.attachmentUrl||null,status:incomeForm.status,...(editingIncome?{changeNote:incomeForm.changeNote||null}:{})};const result=await mutate(editingIncome?`/api/admin/finance/income/${editingIncome}`:'/api/admin/finance/income',editingIncome?'PATCH':'POST',payload);if(result){beginIncome();setMessage('Income saved. Only received records trigger allocations.')}}catch(cause){setError(cause instanceof Error?cause.message:'Enter a valid income amount.')}}
  async function saveTransaction(event:FormEvent){event.preventDefault();try{const payload={title:transactionForm.title,amountMinor:moneyInput(transactionForm.amount,transactionForm.currency),currency:transactionForm.currency.toUpperCase(),transactionType:transactionForm.transactionType,categoryKey:transactionForm.categoryKey||null,transferToCategoryKey:transactionForm.transactionType==='TRANSFER'?transactionForm.transferToCategoryKey:null,subcategoryId:transactionForm.subcategoryId?Number(transactionForm.subcategoryId):null,transactionDate:transactionForm.transactionDate,paymentMethod:transactionForm.paymentMethod||null,description:transactionForm.description||null,attachmentLabel:transactionForm.attachmentLabel||null,attachmentUrl:transactionForm.attachmentUrl||null,goalId:transactionForm.goalId?Number(transactionForm.goalId):null,investmentId:transactionForm.investmentId?Number(transactionForm.investmentId):null,projectId:transactionForm.projectId?Number(transactionForm.projectId):null,learningExperienceId:transactionForm.learningExperienceId?Number(transactionForm.learningExperienceId):null};const result=await mutate(editingTransaction?`/api/admin/finance/transactions/${editingTransaction}`:'/api/admin/finance/transactions',editingTransaction?'PATCH':'POST',payload);if(result){beginTransaction();setMessage('Transaction saved and included in the appropriate balance.')}}catch(cause){setError(cause instanceof Error?cause.message:'Enter a valid transaction amount.')}}
  async function saveSettings(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const primaryCurrency=String(form.get('primaryCurrency')).toUpperCase();const result=await mutate('/api/admin/finance/settings','PATCH',{primaryCurrency,monthStartDay:Number(form.get('monthStartDay')),aiEnabled:form.get('aiEnabled')==='on',allowCsvExport:form.get('allowCsvExport')==='on',allowPrintExport:form.get('allowPrintExport')==='on',includePrivateNotesInAi:form.get('includePrivateNotesInAi')==='on'});if(result)setCurrency(primaryCurrency);}
  async function savePlan(event:FormEvent){event.preventDefault();try{const policy={effectiveDate:planForm.effectiveDate,givingBp:parsePercentToBasisPoints(planForm.giving),essentialBp:parsePercentToBasisPoints(planForm.essential),businessBp:parsePercentToBasisPoints(planForm.business),emergencyBp:parsePercentToBasisPoints(planForm.emergency),investmentBp:parsePercentToBasisPoints(planForm.investment),learningBp:parsePercentToBasisPoints(planForm.learning),enjoymentBp:parsePercentToBasisPoints(planForm.enjoyment),explanation:planForm.explanation};const remainingTotal=policy.essentialBp+policy.businessBp+policy.emergencyBp+policy.investmentBp+policy.learningBp+policy.enjoymentBp;if(remainingTotal!==10000)throw new Error('The six remaining-category percentages must add to 100%.');const confirmed=window.confirm(`Save a new allocation policy effective ${policy.effectiveDate}? Giving first: ${planForm.giving}%. The remaining income will be divided across the six categories as entered. Existing allocation snapshots will not change.`);if(confirmed)await mutate('/api/admin/finance/plans','POST',policy)}catch(cause){setError(cause instanceof Error?cause.message:'Check the percentage values.')}}
  async function saveAdjustment(event:FormEvent){event.preventDefault();try{const payload={categoryKey:adjustment.categoryKey,amountMinor:parseMoneyToMinor(adjustment.amount,selectedCurrency,{allowNegative:true}),currency:selectedCurrency,effectiveDate:adjustment.effectiveDate,explanation:adjustment.explanation};await mutate('/api/admin/finance/budgets','POST',payload);setAdjustment({...adjustment,amount:'',explanation:''})}catch(cause){setError(cause instanceof Error?cause.message:'Enter a valid adjustment amount.')}}
  function beginGoal(goal?:Row){if(goal){setEditingGoalId(goal.id);setGoalForm({goalType:goal.goalType,title:goal.title,target:majorAmount(goal.targetMinor,goal.currency),currency:goal.currency,deadline:goal.deadline??'',notes:goal.notes??''})}else{setEditingGoalId(null);setGoalForm({...goalForm,title:'',target:'',deadline:'',notes:''})}}
  async function saveGoal(event:FormEvent){event.preventDefault();try{const payload=editingGoalId?{title:goalForm.title,targetMinor:moneyInput(goalForm.target,goalForm.currency),deadline:goalForm.deadline||null,notes:goalForm.notes||null}:{goalType:goalForm.goalType,title:goalForm.title,targetMinor:moneyInput(goalForm.target,goalForm.currency),currency:goalForm.currency,deadline:goalForm.deadline||null,notes:goalForm.notes||null};const result=await mutate(editingGoalId?`/api/admin/finance/goals/${editingGoalId}`:'/api/admin/finance/goals',editingGoalId?'PATCH':'POST',payload);if(result)beginGoal()}catch(cause){setError(cause instanceof Error?cause.message:'Enter a valid target.')}}
  function beginInvestment(item?:Row){if(item){setEditingInvestmentId(item.id);setInvestmentForm({name:item.name,investmentCategory:item.investmentCategory,currency:item.currency,currentValue:item.currentValueMinor==null?'':majorAmount(item.currentValueMinor,item.currency),valueAsOf:item.valueAsOf??TODAY(),notes:item.notes??''})}else{setEditingInvestmentId(null);setInvestmentForm({...investmentForm,name:'',currentValue:'',notes:''})}}
  async function saveInvestment(event:FormEvent){event.preventDefault();try{const payload={name:investmentForm.name,investmentCategory:investmentForm.investmentCategory,...(!editingInvestmentId?{currency:investmentForm.currency}:{}),currentValueMinor:investmentForm.currentValue?moneyInput(investmentForm.currentValue,investmentForm.currency):null,valueAsOf:investmentForm.currentValue?investmentForm.valueAsOf:null,notes:investmentForm.notes||null};const result=await mutate(editingInvestmentId?`/api/admin/finance/investments/${editingInvestmentId}`:'/api/admin/finance/investments',editingInvestmentId?'PATCH':'POST',payload);if(result)beginInvestment()}catch(cause){setError(cause instanceof Error?cause.message:'Enter a valid recorded value.')}}
  async function saveCategory(event:FormEvent){event.preventDefault();const name=categoryName.trim();if(!name)return;const result=await mutate('/api/admin/finance/categories','POST',{name,description:categoryDescription||null});if(result){setCategoryName('');setCategoryDescription('')}}
  async function saveSubcategory(event:FormEvent){event.preventDefault();if(!subCategory.name.trim())return;const result=await mutate('/api/admin/finance/categories/subcategories','POST',subCategory);if(result)setSubCategory({...subCategory,name:''})}
  async function askFinanceAssistant(event:FormEvent){event.preventDefault();setAiBusy(true);setInsight('');setError('');try{const response=await fetch('/api/admin/finance/ai',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({question,currency:selectedCurrency,month})});const body=await response.json();if(!response.ok)throw new Error(body.error||'AI insight is unavailable.');setInsight(body.insight)}catch(cause){setError(cause instanceof Error?cause.message:'AI insight is unavailable.')}finally{setAiBusy(false)}}

  if(loading&&!data)return <div className="finance-root finance-state"><Loader2 className="finance-spin"/><p>Loading recorded finance data…</p></div>;
  if(!data)return <div className="finance-root finance-state"><div className="finance-error"><h1>Personal Finance is not ready</h1><p>{error||'Finance records are unavailable.'}</p><p>The forward-only finance migration must be applied before this private workspace can load. No sample financial data is created.</p><button type="button" className="finance-button secondary" onClick={()=>void load()}><RefreshCw size={16}/> Try again</button></div></div>;
  const sectionName=NAV.find((item)=>item.key===section)?.label??'Overview';

  return <main className="finance-root">
    <div className="finance-heading"><div className="finance-brand-icon"><Wallet size={22}/></div><div><p className="finance-eyebrow">PERSONAL STEWARDSHIP</p><h1>Personal Finance</h1><p className="finance-subtitle">A clear, flexible record of how you receive, allocate, spend and build.</p></div><div className="finance-heading-controls"><label>Period<input aria-label="Financial month" type="month" value={month} onChange={(event)=>{setMonth(event.target.value);setMonthTouched(true)}}/></label><label>Currency<select aria-label="Dashboard currency" value={selectedCurrency} onChange={(event)=>setCurrency(event.target.value)}>{currencies.map((value)=><option key={value}>{value}</option>)}{CURRENCY_CHOICES.filter((value)=>!currencies.includes(value)).map((value)=><option key={value}>{value}</option>)}</select></label></div>
    </div>
    <nav className="finance-nav" aria-label="Personal Finance sections">{NAV.map(({key,label,href,icon:Icon})=><Link key={key} href={href} aria-current={section===key?'page':undefined} className={section===key?'active':''}><Icon size={15}/>{label}</Link>)}</nav>
    {(error||message)&&<div className={`finance-notice ${error?'error':'success'}`} role={error?'alert':'status'}>{error||message}</div>}
    {section==='overview'&&<Overview data={data} summary={summary} currency={selectedCurrency} onAsk={askFinanceAssistant} question={question} setQuestion={setQuestion} aiBusy={aiBusy} insight={insight} month={month}/>}
    {section==='income'&&<section className="finance-layout"><div className="finance-panel"><PanelTitle icon={Banknote} title={editingIncome?'Edit income record':'Record income'} subtitle="Expected money is not available until you mark it Received."/><form className="finance-form" onSubmit={saveIncome}><Field label="Income title"><input required maxLength={200} value={incomeForm.title} onChange={e=>updateIncomeField('title',e.target.value)} placeholder="e.g. Website project milestone"/></Field><div className="finance-form-row"><Field label="Amount"><input required inputMode="decimal" value={incomeForm.amount} onChange={e=>updateIncomeField('amount',e.target.value)} placeholder="0.00"/></Field><Field label="Currency"><CurrencyField value={incomeForm.currency} onChange={value=>updateIncomeField('currency',value)}/></Field></div><div className="finance-form-row"><Field label="Income source"><select value={incomeForm.source} onChange={e=>updateIncomeField('source',e.target.value)}>{['Freelance development','Software development projects','Business revenue','Teaching and mentorship','Employment income','Consulting','Other income'].map(value=><option key={value}>{value}</option>)}</select></Field><Field label="Received / expected date"><input required type="date" value={incomeForm.receivedAt} onChange={e=>updateIncomeField('receivedAt',e.target.value)}/></Field></div><div className="finance-form-row"><Field label="Status"><select value={incomeForm.status} onChange={e=>updateIncomeField('status',e.target.value)}><option value="EXPECTED">Expected</option><option value="RECEIVED">Received</option><option value="CANCELLED">Cancelled</option></select></Field><Field label="Payment method"><select value={incomeForm.paymentMethod} onChange={e=>updateIncomeField('paymentMethod',e.target.value)}><option value="">Not specified</option>{['Cash','Bank transfer','Mobile money','Card','Other'].map(value=><option key={value}>{value}</option>)}</select></Field></div><Field label="Description"><textarea rows={3} value={incomeForm.description} onChange={e=>updateIncomeField('description',e.target.value)} maxLength={3000}/></Field><AttachmentFields label={incomeForm.attachmentLabel} url={incomeForm.attachmentUrl} setLabel={value=>updateIncomeField('attachmentLabel',value)} setUrl={value=>updateIncomeField('attachmentUrl',value)}/>{editingIncome&&<Field label="Change note (required for received-income corrections or cancellation)"><input maxLength={500} value={incomeForm.changeNote} onChange={e=>updateIncomeField('changeNote',e.target.value)} placeholder="Explain the correction"/></Field>}<div className="finance-form-actions"><button className="finance-button" type="submit"><Check size={16}/>{editingIncome?'Save income':'Add income'}</button>{editingIncome&&<button type="button" className="finance-button secondary" onClick={()=>beginIncome()}>Cancel edit</button>}</div><p className="finance-help"><ShieldCheck size={14}/>Only <strong>Received</strong> income triggers an allocation. Every saved allocation keeps its policy version and revision.</p></form></div><div className="finance-panel"><PanelTitle icon={Banknote} title="Income history" subtitle="Search records and edit status or details; received changes are versioned."/><div className="finance-toolbar"><Search size={16}/><input aria-label="Search income" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search income"/><select aria-label="Filter income status" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="ALL">All statuses</option><option value="RECEIVED">Received</option><option value="EXPECTED">Expected</option><option value="CANCELLED">Cancelled</option></select></div><div className="finance-record-list">{allIncomes.length?allIncomes.map(row=><article className="finance-record" key={row.id}><div><strong>{row.title}</strong><span>{row.source} · {row.receivedAt} · {row.status}</span>{row.status==='RECEIVED'&&<small>{row.allocationRevision?`Allocation revision ${row.allocationRevision}`:'Allocation processing pending'}</small>}</div><b>{formatMinor(row.amountMinor,row.currency)}</b><button className="finance-icon-button" onClick={()=>beginIncome(row)} aria-label={`Edit ${row.title}`}><Pencil size={15}/></button></article>):<Empty text="No income records match this search. Add an actual record when money is expected or received."/>}</div></div></section>}
    {section==='allocation'&&<AllocationSection data={data} planForm={planForm} setPlanForm={setPlanForm} savePlan={savePlan} currency={selectedCurrency}/>}
    {section==='transactions'&&<section className="finance-layout"><div className="finance-panel"><PanelTitle icon={Activity} title={editingTransaction?'Edit transaction':'Add transaction'} subtitle="Transfers and savings/investment contributions change allocations without counting as income or expenses."/><form className="finance-form" onSubmit={saveTransaction}><Field label="Title"><input required maxLength={200} value={transactionForm.title} onChange={e=>updateTransactionField('title',e.target.value)}/></Field><div className="finance-form-row"><Field label="Amount"><input required inputMode="decimal" value={transactionForm.amount} onChange={e=>updateTransactionField('amount',e.target.value)} placeholder="0.00"/></Field><Field label="Currency"><CurrencyField value={transactionForm.currency} onChange={value=>updateTransactionField('currency',value)}/></Field></div><div className="finance-form-row"><Field label="Transaction type"><select value={transactionForm.transactionType} onChange={e=>{const value=e.target.value;updateTransactionField('transactionType',value);if(value==='GIVING')updateTransactionField('categoryKey','GIVING');if(value==='SAVINGS_CONTRIBUTION'||value==='SAVINGS_WITHDRAWAL')updateTransactionField('categoryKey','EMERGENCY');if(value==='INVESTMENT_CONTRIBUTION'||value==='INVESTMENT_WITHDRAWAL')updateTransactionField('categoryKey','LONG_TERM_INVESTMENT')}}>{[['EXPENSE','Expense'],['GIVING','Giving'],['TRANSFER','Transfer between allocations'],['SAVINGS_CONTRIBUTION','Savings contribution'],['SAVINGS_WITHDRAWAL','Savings withdrawal'],['INVESTMENT_CONTRIBUTION','Investment contribution'],['INVESTMENT_WITHDRAWAL','Investment withdrawal']].map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></Field><Field label="Date"><input type="date" required value={transactionForm.transactionDate} onChange={e=>updateTransactionField('transactionDate',e.target.value)}/></Field></div><div className="finance-form-row"><Field label={transactionForm.transactionType==='TRANSFER'?'From category':'Financial category'}><select required value={transactionForm.categoryKey} onChange={e=>updateTransactionField('categoryKey',e.target.value)}>{cats.map(cat=><option key={cat.key} value={cat.key}>{cat.name}</option>)}</select></Field>{transactionForm.transactionType==='TRANSFER'?<Field label="To category"><select value={transactionForm.transferToCategoryKey} onChange={e=>updateTransactionField('transferToCategoryKey',e.target.value)}>{cats.filter(cat=>cat.key!==transactionForm.categoryKey).map(cat=><option key={cat.key} value={cat.key}>{cat.name}</option>)}</select></Field>:<Field label="Subcategory"><select value={transactionForm.subcategoryId} onChange={e=>updateTransactionField('subcategoryId',e.target.value)}><option value="">Not specified</option>{data.subcategories.filter(row=>row.categoryKey===transactionForm.categoryKey&&row.isActive).map(row=><option key={row.id} value={row.id}>{row.name}</option>)}</select></Field>}</div>{transactionForm.transactionType.startsWith('SAVINGS_')&&<Field label="Savings goal"><select required value={transactionForm.goalId} onChange={e=>updateTransactionField('goalId',e.target.value)}><option value="">Choose goal</option>{data.goals.filter(row=>row.isActive&&row.currency===transactionForm.currency).map(row=><option key={row.id} value={row.id}>{row.title}</option>)}</select></Field>}{transactionForm.transactionType.startsWith('INVESTMENT_')&&<Field label="Investment record"><select required value={transactionForm.investmentId} onChange={e=>updateTransactionField('investmentId',e.target.value)}><option value="">Choose investment</option>{data.investments.filter(row=>row.isActive&&row.currency===transactionForm.currency).map(row=><option key={row.id} value={row.id}>{row.name}</option>)}</select></Field>}{transactionForm.categoryKey==='BUSINESS'&&<Field label="Business / project (optional)"><select value={transactionForm.projectId} onChange={e=>updateTransactionField('projectId',e.target.value)}><option value="">No linked project</option>{data.projects.map(row=><option key={row.id} value={row.id}>{row.title}</option>)}</select></Field>}{transactionForm.categoryKey==='LEARNING'&&<Field label="Learning record (optional)"><select value={transactionForm.learningExperienceId} onChange={e=>updateTransactionField('learningExperienceId',e.target.value)}><option value="">No linked learning record</option>{data.learningExperiences.map(row=><option key={row.id} value={row.id}>{row.title}</option>)}</select></Field>}<div className="finance-form-row"><Field label="Payment method"><input value={transactionForm.paymentMethod} onChange={e=>updateTransactionField('paymentMethod',e.target.value)} maxLength={100}/></Field><Field label="Description"><input value={transactionForm.description} onChange={e=>updateTransactionField('description',e.target.value)} maxLength={1000}/></Field></div><AttachmentFields label={transactionForm.attachmentLabel} url={transactionForm.attachmentUrl} setLabel={value=>updateTransactionField('attachmentLabel',value)} setUrl={value=>updateTransactionField('attachmentUrl',value)}/><div className="finance-form-actions"><button className="finance-button" type="submit"><Check size={16}/>{editingTransaction?'Save transaction':'Add transaction'}</button>{editingTransaction&&<button type="button" className="finance-button secondary" onClick={()=>beginTransaction()}>Cancel edit</button>}</div></form></div><div className="finance-panel"><PanelTitle icon={Activity} title="Transaction history" subtitle="Income records appear here from Income. Transfers remain neutral in cash-flow totals."/><div className="finance-toolbar"><Search size={16}/><input aria-label="Search transactions" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search transactions"/></div><TransactionList rows={allTransactions} categories={data.categories} onEdit={beginTransaction} onDelete={async row=>{if(window.confirm(`Delete “${row.title}”? It will be removed from totals but retained in history.`))await mutate(`/api/admin/finance/transactions/${row.id}`,'DELETE')}}/></div></section>}
    {section==='budgets'&&<section className="finance-section"><div className="finance-panel"><PanelTitle icon={TrendingUp} title="Category budgets" subtitle={`Stored allocations and outflows from ${summary?.start??month} to ${summary?.endExclusive??''}. Transfers and contributions change available allocation but are not expenses.`}/><div className="finance-budget-list">{data.summary.budgets.map(row=><BudgetRow key={row.categoryKey} row={row} currency={selectedCurrency}/>)}</div></div><div className="finance-panel"><PanelTitle icon={ArrowUpRight} title="Adjust a category budget" subtitle="Adjustments require an explanation and never change your percentage plan."/><form className="finance-form finance-inline-form" onSubmit={saveAdjustment}><Field label="Category"><select value={adjustment.categoryKey} onChange={e=>setAdjustment({...adjustment,categoryKey:e.target.value})}>{cats.map(cat=><option key={cat.key} value={cat.key}>{cat.name}</option>)}</select></Field><Field label={`Adjustment amount (${selectedCurrency}; negative reduces)`}><input required inputMode="decimal" value={adjustment.amount} onChange={e=>setAdjustment({...adjustment,amount:e.target.value})}/></Field><Field label="Effective date"><input type="date" required value={adjustment.effectiveDate} onChange={e=>setAdjustment({...adjustment,effectiveDate:e.target.value})}/></Field><Field label="Explanation"><textarea required minLength={3} maxLength={500} rows={3} value={adjustment.explanation} onChange={e=>setAdjustment({...adjustment,explanation:e.target.value})}/></Field><button className="finance-button"><Check size={16}/>Record explained adjustment</button></form></div></section>}
    {section==='savings'&&<section className="finance-section"><div className="finance-panel"><PanelTitle icon={Target} title="Savings goals" subtitle="Balances come from recorded contributions and withdrawals; the target is set by you."/><form className="finance-form finance-inline-form" onSubmit={saveGoal}><div className="finance-form-row"><Field label="Goal type"><select disabled={editingGoalId!==null} value={goalForm.goalType} onChange={e=>setGoalForm({...goalForm,goalType:e.target.value})}><option value="GOAL">Personal goal</option><option value="EMERGENCY">Emergency fund</option></select></Field><Field label="Goal name"><input required value={goalForm.title} onChange={e=>setGoalForm({...goalForm,title:e.target.value})} placeholder="e.g. Development laptop"/></Field></div><div className="finance-form-row"><Field label="Target"><input required inputMode="decimal" value={goalForm.target} onChange={e=>setGoalForm({...goalForm,target:e.target.value})}/></Field><Field label="Currency">{editingGoalId?<input value={goalForm.currency} readOnly/>:<CurrencyField value={goalForm.currency} onChange={value=>setGoalForm({...goalForm,currency:value})}/>}</Field></div><div className="finance-form-row"><Field label="Deadline (optional)"><input type="date" value={goalForm.deadline} onChange={e=>setGoalForm({...goalForm,deadline:e.target.value})}/></Field><Field label="Notes"><input value={goalForm.notes} onChange={e=>setGoalForm({...goalForm,notes:e.target.value})} maxLength={1000}/></Field></div><div className="finance-form-actions"><button className="finance-button"><Plus size={16}/>{editingGoalId?'Save goal':'Create goal'}</button>{editingGoalId&&<button type="button" className="finance-button secondary" onClick={()=>beginGoal()}>Cancel edit</button>}</div></form><div className="finance-goal-list">{data.summary.goals.map(goal=><GoalCard key={goal.id} goal={goal} currency={goal.currency} onEdit={()=>beginGoal(goal)}/>)}</div>{!data.summary.goals.length&&<Empty text="No savings goals have been recorded yet."/>}<Link className="finance-inline-link" href="/admin/finance/transactions">Record a savings contribution or withdrawal <ArrowUpRight size={15}/></Link></div><div className="finance-panel"><PanelTitle icon={Landmark} title="Long-term investments" subtitle="Manual records only. No orders or return projections are made."/><form className="finance-form finance-inline-form" onSubmit={saveInvestment}><Field label="Investment name"><input required value={investmentForm.name} onChange={e=>setInvestmentForm({...investmentForm,name:e.target.value})} placeholder="e.g. Retirement account"/></Field><div className="finance-form-row"><Field label="Investment category"><select value={investmentForm.investmentCategory} onChange={e=>setInvestmentForm({...investmentForm,investmentCategory:e.target.value})}>{['Regulated savings product','Fixed-term deposit','Diversified investment fund','Retirement savings','Other manually tracked investment'].map(value=><option key={value}>{value}</option>)}</select></Field><Field label="Currency"><CurrencyField value={investmentForm.currency} onChange={value=>setInvestmentForm({...investmentForm,currency:value})}/></Field></div><div className="finance-form-row"><Field label="Current value (optional)"><input inputMode="decimal" value={investmentForm.currentValue} onChange={e=>setInvestmentForm({...investmentForm,currentValue:e.target.value})} placeholder="Not recorded"/></Field><Field label="Value as of"><input type="date" value={investmentForm.valueAsOf} onChange={e=>setInvestmentForm({...investmentForm,valueAsOf:e.target.value})}/></Field></div><Field label="Notes"><textarea rows={2} value={investmentForm.notes} onChange={e=>setInvestmentForm({...investmentForm,notes:e.target.value})}/></Field><div className="finance-form-actions"><button className="finance-button"><Plus size={16}/>{editingInvestmentId?'Save investment':'Add manual investment record'}</button>{editingInvestmentId&&<button type="button" className="finance-button secondary" onClick={()=>beginInvestment()}>Cancel edit</button>}</div></form><div className="finance-record-list">{data.summary.investments.map(item=><article className="finance-record" key={item.id}><div><strong>{item.name}</strong><span>{item.investmentCategory} · net contributions {formatMinor(item.netContributedMinor,item.currency)}</span><small>{item.currentValueMinor!=null?`Recorded value ${formatMinor(item.currentValueMinor,item.currency)} as of ${item.valueAsOf??'date not set'}`:'Current value not recorded'}</small></div><b>{formatMinor(item.trackedValueMinor,item.currency)}</b><button className="finance-icon-button" onClick={()=>beginInvestment(item)} aria-label={`Edit ${item.name}`}><Pencil size={14}/></button></article>)}</div>{!data.summary.investments.length&&<Empty text="No long-term investment records have been added."/>}<Link className="finance-inline-link" href="/admin/finance/transactions">Record an investment contribution or withdrawal <ArrowUpRight size={15}/></Link></div></section>}
    {section==='reports'&&<section className="finance-section finance-report" id="finance-print"><div className="finance-panel"><div className="finance-panel-heading"><PanelTitle icon={FileText} title="Financial reports" subtitle="Choose the reporting period and currency. Values are calculated only from saved records."/><div className="finance-report-controls"><label>Report<select value={reportPeriod} onChange={e=>setReportPeriod(e.target.value)}><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option><option value="annual">Annual</option></select></label>{reportPeriod==='monthly'?<label>Month<input type="month" value={month} onChange={e=>{setMonth(e.target.value);setMonthTouched(true)}}/></label>:reportPeriod==='quarterly'?<label>Quarter<input value={reportQuarter} onChange={e=>setReportQuarter(e.target.value)} placeholder="2026-Q4"/></label>:<label>Year<input value={reportYear} onChange={e=>setReportYear(e.target.value)} inputMode="numeric" maxLength={4}/></label>}</div><div className="finance-form-actions">{data.settings.allowCsvExport?<a className="finance-button" href={reportCsvHref(reportPeriod,month,reportQuarter,reportYear,selectedCurrency)}><Download size={16}/>Download CSV</a>:<button className="finance-button" disabled><Download size={16}/>CSV export disabled</button>}<button className="finance-button secondary" type="button" onClick={()=>window.print()} disabled={!data.settings.allowPrintExport}><Printer size={16}/>Print / Save PDF</button></div></div>{reportLoading&&<p role="status">Calculating this report from saved records…</p>}{reportData&&<><p className="finance-help">{reportData.period} · {reportData.start} to {reportData.endExclusive} (end exclusive) · {reportData.currency}</p><div className="finance-report-summary"><Metric label="Income received" value={formatMinor(reportData.totals.incomeMinor,reportData.currency)}/><Metric label="Allocated" value={formatMinor(reportData.totals.allocatedMinor,reportData.currency)}/><Metric label="Expenses" value={formatMinor(reportData.totals.expensesMinor,reportData.currency)}/><Metric label="Giving" value={formatMinor(reportData.totals.givingMinor,reportData.currency)}/></div><p className="finance-help">Net cash flow this period: <strong>{formatMinor(reportData.totals.availableCashFlowMinor,reportData.currency)}</strong>. Savings and investment contributions are tracked separately from expenses.</p><h3>Allocation and spending by category</h3><table className="finance-table"><thead><tr><th>Category</th><th>Allocated</th><th>Spent</th><th>Remaining</th><th>Utilized</th></tr></thead><tbody>{reportData.categories.map((row:Row)=><tr key={row.categoryKey}><td>{row.name}</td><td>{formatMinor(row.allocatedMinor,reportData.currency)}</td><td>{formatMinor(row.spentMinor,reportData.currency)}</td><td>{formatMinor(row.remainingMinor,reportData.currency)}</td><td>{(row.utilizedBp/100).toFixed(1)}%</td></tr>)}</tbody></table><h3>Actual transactions in this period</h3>{reportData.transactions.length?<div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>Date</th><th>Type</th><th>Title</th><th>Category</th><th>Amount</th></tr></thead><tbody>{reportData.transactions.map((row:Row)=><tr key={row.id}><td>{row.transactionDate}</td><td>{row.transactionType}</td><td>{row.title}</td><td>{row.categoryKey??'—'}</td><td>{formatMinor(row.amountMinor,row.currency)}</td></tr>)}</tbody></table></div>:<Empty text="No transaction records fall in this selected period."/>}</>}<p className="finance-help">PDF is produced from the browser’s print dialog. CSV export uses stored ledger and allocation records with spreadsheet-formula escaping.</p></div></section>}
    {section==='settings'&&<section className="finance-section"><div className="finance-panel"><PanelTitle icon={Settings2} title="Finance preferences" subtitle="Currency/month preferences do not rewrite any income, plan or historical allocation."/><form className="finance-form" onSubmit={saveSettings}><div className="finance-form-row"><Field label="Primary currency"><CurrencyField key={data.settings.primaryCurrency??'ETB'} name="primaryCurrency" value={data.settings.primaryCurrency??'ETB'}/></Field><Field label="Financial month starts on day (1–28)"><input required type="number" name="monthStartDay" min="1" max="28" defaultValue={data.settings.monthStartDay??1} key={data.settings.monthStartDay??1}/></Field></div><label className="finance-check"><input type="checkbox" name="aiEnabled" defaultChecked={data.settings.aiEnabled}/>Enable AI finance insights using saved records when I request them.</label><label className="finance-check"><input type="checkbox" name="includePrivateNotesInAi" defaultChecked={data.settings.includePrivateNotesInAi}/>Allow my transaction descriptions/private notes to be included in requested AI analysis. Off by default.</label><label className="finance-check"><input type="checkbox" name="allowCsvExport" defaultChecked={data.settings.allowCsvExport}/>Allow CSV export of my finance records.</label><label className="finance-check"><input type="checkbox" name="allowPrintExport" defaultChecked={data.settings.allowPrintExport}/>Allow print / Save as PDF from reports.</label><button className="finance-button"><Check size={16}/>Save preferences</button><p className="finance-help"><ShieldCheck size={14}/>Finance APIs are admin-only. AI requests are not persisted as conversations. New allocation plans require an effective date; past snapshots stay unchanged.</p></form></div><div className="finance-panel"><PanelTitle icon={Settings2} title="Categories and subcategories" subtitle="Add and rename categories; retire custom labels without removing existing transaction history."/><form className="finance-form finance-inline-form" onSubmit={saveCategory}><Field label="New category"><input required value={categoryName} onChange={e=>setCategoryName(e.target.value)} maxLength={100}/></Field><Field label="Description"><input value={categoryDescription} onChange={e=>setCategoryDescription(e.target.value)} maxLength={500}/></Field><button className="finance-button"><Plus size={16}/>Add category</button></form><form className="finance-form finance-inline-form" onSubmit={saveSubcategory}><Field label="Parent category"><select value={subCategory.categoryKey} onChange={e=>setSubCategory({...subCategory,categoryKey:e.target.value})}>{cats.map(cat=><option key={cat.key} value={cat.key}>{cat.name}</option>)}</select></Field><Field label="New subcategory"><input required value={subCategory.name} onChange={e=>setSubCategory({...subCategory,name:e.target.value})} maxLength={100}/></Field><button className="finance-button secondary"><Plus size={16}/>Add subcategory</button></form><div className="finance-category-manage">{cats.map(cat=><div className="finance-category-manage-row" key={cat.key}><strong>{cat.name}</strong><small>{cat.key}{cat.isDefault?' · core allocation':''}</small><button className="finance-button tiny secondary" onClick={async()=>{const name=window.prompt('Rename category',cat.name);if(name?.trim())await mutate(`/api/admin/finance/categories/${cat.key}`,'PATCH',{name:name.trim()})}}>Rename</button>{!cat.isDefault&&<button className="finance-icon-button danger" aria-label={`Disable ${cat.name}`} onClick={async()=>{if(window.confirm(`Retire ${cat.name}? Past records remain.`))await mutate(`/api/admin/finance/categories/${cat.key}`,'PATCH',{isActive:false})}}><Trash2 size={14}/></button>}</div>)}</div>{data.subcategories.length>0&&<details className="finance-details"><summary>Manage subcategories ({data.subcategories.length})</summary><div className="finance-category-manage">{data.subcategories.filter(row=>row.isActive).map(sub=><div className="finance-category-manage-row" key={sub.id}><strong>{sub.name}</strong><small>{data.categories.find(cat=>cat.key===sub.categoryKey)?.name}</small><button className="finance-button tiny secondary" onClick={async()=>{const name=window.prompt('Rename subcategory',sub.name);if(name?.trim())await mutate(`/api/admin/finance/categories/subcategories/${sub.id}`,'PATCH',{name:name.trim()})}}>Rename</button><button className="finance-icon-button danger" aria-label={`Retire ${sub.name}`} onClick={async()=>{if(window.confirm(`Retire ${sub.name}? Past transaction history is preserved.`))await mutate(`/api/admin/finance/categories/subcategories/${sub.id}`,'PATCH',{isActive:false})}}><Trash2 size={14}/></button></div>)}</div></details>}</div></section>}
    <footer className="finance-footnote"><ShieldCheck size={14}/>Stored records only · No bank connections or investment execution · Currency totals remain separate · {sectionName}</footer>
  </main>;
}

function Overview({data,summary,currency,onAsk,question,setQuestion,aiBusy,insight,month}:{data:Snapshot;summary:Row|undefined;currency:string;onAsk:(event:FormEvent)=>void;question:string;setQuestion:(value:string)=>void;aiBusy:boolean;insight:string;month:string}){
 const iconMap:Record<string,any>={GIVING:Gift,ESSENTIAL:Heart,BUSINESS:Briefcase,EMERGENCY:ShieldCheck,LONG_TERM_INVESTMENT:TrendingUp,LEARNING:BookOpen,ENJOYMENT:Sparkles};
 const cards=[['Income received',summary?.incomeReceivedMinor??'0',Banknote],['Total allocated',summary?.totalAllocatedMinor??'0',ArrowLeftRight],['Expenses',summary?.totalExpensesMinor??'0',TrendingUp],['Available (tracked)',summary?.availableBalanceMinor??'0',Wallet]] as const;
 return <section className="finance-section"><div className="finance-metrics">{cards.map(([label,value,Icon])=><Metric key={label} label={label} value={formatMinor(value,currency)} icon={Icon}/>)}</div><div className="finance-overview-grid"><div className="finance-panel"><PanelTitle icon={ArrowLeftRight} title="This period’s allocation" subtitle="Giving is calculated first; the six plan shares apply to the remaining 90%."/><div className="finance-allocation-list">{data.summary.budgets.map(row=>{const Icon=iconMap[row.categoryKey]??Wallet;return <div className="finance-allocation-row" key={row.categoryKey}><div className="finance-allocation-heading"><span className="finance-category-icon"><Icon size={16}/></span><strong>{row.name}</strong><b>{formatMinor(row.allocatedMinor,currency)}</b></div><div className="finance-progress"><span style={{width:shareWidth(row.allocatedMinor,summary?.totalAllocatedMinor??'0')}}/></div><div className="finance-allocation-meta"><span>{formatMinor(row.spentMinor,currency)} spent</span><span>{formatMinor(row.remainingMinor,currency)} remaining</span></div></div>})}</div></div><div className="finance-panel"><PanelTitle icon={TrendingUp} title="Planned vs actual" subtitle="Category utilization for saved expenses and committed contributions."/><div className="finance-budget-list">{data.summary.budgets.map(row=><BudgetRow key={row.categoryKey} row={row} currency={currency}/>)}</div></div><div className="finance-panel"><PanelTitle icon={Activity} title="Six-period trend" subtitle="Recorded income compared with recorded expenses."/><TrendChart trends={data.summary.trends} currency={currency}/></div><div className="finance-panel"><PanelTitle icon={Target} title="Goals and progress" subtitle="Balances derive from contribution and withdrawal records."/><div className="finance-goal-list">{data.summary.goals.slice(0,4).map(goal=><GoalCard key={goal.id} goal={goal} currency={currency}/>)}</div>{!data.summary.goals.length&&<Empty text="No financial goals recorded yet."/>}<Link className="finance-inline-link" href="/admin/finance/savings">Manage savings and investment records <ArrowUpRight size={15}/></Link></div><div className="finance-panel"><PanelTitle icon={Activity} title="Recent transactions" subtitle={`Actual records in ${currency}.`} /><TransactionList rows={data.summary.recentTransactions} categories={data.categories}/>{!data.summary.recentTransactions.length&&<Empty text="No transactions recorded yet."/>}</div><div className="finance-panel finance-special-balances"><PanelTitle icon={Wallet} title="Allocation balances" subtitle="Remaining period allocation, not a bank balance."/><Balance label="Giving allocated · actually given" value={`${formatMinor(summary?.givingAllocatedMinor??'0',currency)} · ${formatMinor(summary?.amountGivenMinor??'0',currency)}`}/><Balance label="Business reinvestment balance" value={formatMinor(summary?.businessReinvestmentBalanceMinor??'0',currency)}/><Balance label="Emergency savings balance" value={formatMinor(summary?.emergencySavingsBalanceMinor??'0',currency)}/><Balance label="Long-term investment balance" value={formatMinor(summary?.longTermInvestmentBalanceMinor??'0',currency)}/><Balance label="Learning budget balance" value={formatMinor(summary?.learningBudgetBalanceMinor??'0',currency)}/><Balance label="Personal enjoyment balance" value={formatMinor(summary?.personalEnjoymentBalanceMinor??'0',currency)}/></div></div><div className="finance-panel finance-ai-panel"><PanelTitle icon={Sparkles} title="AI Financial Assistant" subtitle={data.settings.aiEnabled?'Optional, on-demand analysis of saved finance records.':'Enable AI insight consent in Finance Settings to use this assistant.'}/><form className="finance-ai-form" onSubmit={onAsk}><label className="finance-field"><span>Your question</span><textarea rows={2} maxLength={1000} disabled={!data.settings.aiEnabled||aiBusy} value={question} onChange={e=>setQuestion(e.target.value)}/></label><button className="finance-button" disabled={!data.settings.aiEnabled||aiBusy}>{aiBusy?<Loader2 className="finance-spin" size={16}/>:<Sparkles size={16}/>}Analyze {month} records</button></form>{insight&&<div className="finance-insight" aria-live="polite"><strong>AI-generated suggestion · based on recorded data</strong><p>{insight}</p><small>Educational suggestions only; verify your records. No investment returns are promised.</small></div>}</div></section>
}

function AllocationSection({data,planForm,setPlanForm,savePlan,currency}:{data:Snapshot;planForm:Record<string,string>;setPlanForm:(value:any)=>void;savePlan:(event:FormEvent)=>void;currency:string}){
 const latest=data.plans[0];const relative=[['Essential living','essentialBp'],['Business reinvestment','businessBp'],['Emergency savings','emergencyBp'],['Long-term investments','investmentBp'],['Learning and skills','learningBp'],['Personal enjoyment','enjoymentBp']] as const;
 return <section className="finance-section"><div className="finance-panel"><PanelTitle icon={ArrowLeftRight} title="Your two-stage allocation philosophy" subtitle="Every received income record gets its own immutable allocation snapshot."/><div className="finance-stage-card finance-giving-stage"><span>STAGE 1 · FIRST ALLOCATION</span><h3>Giving to God</h3><strong>{formatBasisPoints(latest?.givingBp??1000)} of total received income</strong><p>Always allocated before the remaining categories.</p></div><div className="finance-stage-card finance-plan-stage"><span>STAGE 2 · REMAINING {formatBasisPoints(10000-(latest?.givingBp??1000))}</span><h3>Entrepreneur’s Monthly Financial Spending Plan</h3><div className="finance-relative-list">{relative.map(([label,key])=><div key={key}><span>{label}</span><strong>{formatBasisPoints(latest?.[key]??0)} of remaining income</strong><small>Effective share of total at the current first-stage rate: {formatBasisPoints(Math.round((latest?.[key]??0)*(10000-(latest?.givingBp??1000))/10000))}</small></div>)}</div><p className="finance-effective-total">These six values must total 100% of the remaining income. They are never applied directly to 100% of income.</p></div><div className="finance-callout"><Check size={17}/><span>Allocation uses integer minor units and deterministic largest-remainder rounding. Giving and all six categories reconcile exactly to each received income.</span></div></div><div className="finance-panel"><PanelTitle icon={Pencil} title="Create a future plan version" subtitle="Confirm the effective date and explain the change. Existing income snapshots are never rewritten."/><form className="finance-form" onSubmit={savePlan}><Field label="New plan effective date"><input required type="date" value={planForm.effectiveDate} onChange={e=>setPlanForm({...planForm,effectiveDate:e.target.value})}/></Field><Field label="Giving first (% of total income)"><input required inputMode="decimal" value={planForm.giving} onChange={e=>setPlanForm({...planForm,giving:e.target.value})}/></Field><div className="finance-form-row">{relative.map(([label,key])=><Field key={key} label={`${label} (% of remaining income)`}><input required inputMode="decimal" value={planForm[key.replace('Bp','')]??planForm[key]} onChange={e=>setPlanForm({...planForm,[key.replace('Bp','')]:e.target.value})}/></Field>)}</div><Field label="Explanation"><textarea required minLength={3} maxLength={500} rows={3} value={planForm.explanation} onChange={e=>setPlanForm({...planForm,explanation:e.target.value})} placeholder="Why is a new plan needed?"/></Field><button className="finance-button"><Check size={16}/>Review and save future plan</button><p className="finance-help">The six post-giving inputs must sum to 100%. A confirmation names the effective date before the server saves the new version.</p></form></div><div className="finance-panel finance-full"><PanelTitle icon={CalendarDays} title="Allocation history" subtitle="Plan versions and allocation runs are stored for audit and never merged across currencies."/><div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>Effective / received</th><th>Source</th><th>Amount</th><th>Giving first</th><th>Revision / plan</th><th>Reason</th></tr></thead><tbody>{data.runs.filter(run=>run.currency===currency).map(run=>{const income=data.incomes.find(row=>row.id===run.incomeId);const plan=data.plans.find(row=>row.id===run.planId);return <tr key={run.id}><td>{income?.receivedAt??run.createdAt?.slice(0,10)}</td><td>{income?.title??'Received income'}</td><td>{formatMinor(run.incomeAmountMinor,run.currency)}</td><td>{formatMinor(run.givingAmountMinor,run.currency)}</td><td>#{run.revision} · plan {plan?.effectiveDate??'—'}</td><td>{run.reason}</td></tr>})}</tbody></table>{!data.runs.some(run=>run.currency===currency)&&<Empty text="No received income has created an allocation snapshot yet."/>}</div></div></section>
}

function TransactionList({rows,categories,onEdit,onDelete}:{rows:Row[];categories:Row[];onEdit?:(row:Row)=>void;onDelete?:(row:Row)=>void}){
 if(!rows.length)return <Empty text="No matching transaction records."/>;
 const labelMap:Record<string,string>={INCOME:'Income',EXPENSE:'Expense',GIVING:'Giving',TRANSFER:'Transfer',SAVINGS_CONTRIBUTION:'Savings contribution',SAVINGS_WITHDRAWAL:'Savings withdrawal',INVESTMENT_CONTRIBUTION:'Investment contribution',INVESTMENT_WITHDRAWAL:'Investment withdrawal'};
 return <div className="finance-record-list">{rows.slice(0,100).map(row=><article className="finance-record" key={`${row.sourceIncomeId?'income-':''}${row.id}`}><div><strong>{row.title}</strong><span>{labelMap[row.transactionType]??row.transactionType.replaceAll('_',' ')} · {row.transactionDate}{row.categoryKey?` · ${categories.find(cat=>cat.key===row.categoryKey)?.name??row.categoryKey}`:''}{row.transferToCategoryKey?` → ${categories.find(cat=>cat.key===row.transferToCategoryKey)?.name??row.transferToCategoryKey}`:''}</span>{row.description&&<small>{row.description}</small>}</div><b className={row.transactionType==='EXPENSE'||row.transactionType==='GIVING'?'negative':''}>{row.transactionType==='EXPENSE'||row.transactionType==='GIVING'?'−':''}{formatMinor(row.amountMinor,row.currency)}</b>{row.sourceIncomeId&&<small className="finance-linked">Income record</small>}{onEdit&&!row.sourceIncomeId&&<button className="finance-icon-button" onClick={()=>onEdit(row)} aria-label={`Edit ${row.title}`}><Pencil size={14}/></button>}{onDelete&&!row.sourceIncomeId&&<button className="finance-icon-button danger" onClick={()=>onDelete(row)} aria-label={`Delete ${row.title}`}><Trash2 size={14}/></button>}</article>)}</div>
}
function BudgetRow({row,currency}:{row:Row;currency:string}){return <div className={`finance-budget-row${row.overBudget?' over':''}`}><div className="finance-budget-top"><strong>{row.name}</strong><span>{formatMinor(row.allocatedMinor,currency)} allocated</span></div><div className="finance-progress"><span style={{width:pctWidth(row.utilizedBp),background:row.overBudget?'var(--finance-terracotta)':'var(--finance-forest)'}}/></div><div className="finance-budget-bottom"><span>{formatMinor(row.spentMinor,currency)} spent</span><span>{formatMinor(row.remainingMinor,currency)} remaining allocation</span><small>{Math.max(0,row.utilizedBp/100).toFixed(1)}% used</small></div>{row.overBudget&&<small className="finance-over-budget">Spending and committed outflows exceed this category’s current allocation.</small>}</div>}
function GoalCard({goal,currency,onEdit}:{goal:Row;currency:string;onEdit?:()=>void}){return <article className="finance-goal-card"><div className="finance-goal-head"><div><strong>{goal.title}</strong><span>{goal.goalType==='EMERGENCY'?'Emergency fund':'Financial goal'}{goal.deadline?` · target ${goal.deadline}`:''}</span></div><b>{formatMinor(goal.currentMinor,currency)} / {formatMinor(goal.targetMinor,currency)}</b></div><div className="finance-progress"><span style={{width:pctWidth(goal.progressBp)}}/></div><small>{(goal.progressBp/100).toFixed(1)}% of target · recorded contributions less withdrawals</small>{onEdit&&<button type="button" className="finance-icon-button" onClick={onEdit} aria-label={`Edit ${goal.title}`}><Pencil size={13}/></button>}</article>}
function TrendChart({trends,currency}:{trends:Row[];currency:string}){const max=trends.reduce((value,row)=>{const current=BigInt(row.incomeMinor)>BigInt(row.expensesMinor)?BigInt(row.incomeMinor):BigInt(row.expensesMinor);return current>value?current:value},BigInt(1));return <div className="finance-trends" role="img" aria-label={`Six periods of recorded income and expenses in ${currency}`}>{trends.map(row=>{const income=Number((BigInt(row.incomeMinor)*BigInt(10000))/max)/100;const expenses=Number((BigInt(row.expensesMinor)*BigInt(10000))/max)/100;return <div className="finance-trend-column" key={row.month}><div className="finance-trend-bars"><span title={`Income ${formatMinor(row.incomeMinor,currency)}`} className="income" style={{height:`${Math.max(2,Math.min(100,income))}%`}}/><span title={`Expenses ${formatMinor(row.expensesMinor,currency)}`} className="expense" style={{height:`${Math.max(2,Math.min(100,expenses))}%`}}/></div><small>{row.month.slice(5)}</small></div>})}<div className="finance-trend-legend"><span><i className="income"/> Income</span><span><i className="expense"/> Expenses</span></div></div>}
function Metric({label,value,icon:Icon}:{label:string;value:string;icon?:any}){return <article className="finance-metric">{Icon&&<span><Icon size={17}/></span>}<small>{label}</small><strong>{value}</strong></article>}
function Balance({label,value}:{label:string;value:string}){return <div className="finance-balance"><span>{label}</span><strong>{value}</strong></div>}
function PanelTitle({icon:Icon,title,subtitle}:{icon:any;title:string;subtitle:string}){return <div className="finance-panel-title"><span className="finance-panel-icon"><Icon size={17}/></span><div><h2>{title}</h2><p>{subtitle}</p></div></div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="finance-field"><span>{label}</span>{children}</label>}
function CurrencyField({value,onChange,name}:{value:string;onChange?:(value:string)=>void;name?:string}){return onChange ? <input aria-label="Currency code" name={name} required minLength={3} maxLength={3} pattern="[A-Za-z]{3}" value={value} onChange={event=>onChange(event.target.value.toUpperCase())} list="finance-currency-options"/> : <input aria-label="Currency code" name={name} required minLength={3} maxLength={3} pattern="[A-Za-z]{3}" defaultValue={value} list="finance-currency-options"/>}
function AttachmentFields({label,url,setLabel,setUrl}:{label:string;url:string;setLabel:(value:string)=>void;setUrl:(value:string)=>void}){return <div className="finance-form-row"><Field label="Attachment label (optional)"><input value={label} maxLength={200} onChange={e=>setLabel(e.target.value)} placeholder="Receipt or statement"/></Field><Field label="Attachment HTTPS URL or storage reference"><input type="text" value={url} maxLength={2048} onChange={e=>setUrl(e.target.value)} placeholder="https://… or /manus-storage/…"/></Field><datalist id="finance-currency-options">{CURRENCY_CHOICES.map(code=><option key={code} value={code}/>)}</datalist></div>}
function Empty({text}:{text:string}){return <div className="finance-empty"><Wallet size={20}/><p>{text}</p></div>}
function majorAmount(minor:string,currency:string){try{return formatMajorInput(minor,currency)}catch{return ''}}
function reportJsonHref(period:string,month:string,quarter:string,year:string,currency:string){const params=new URLSearchParams({format:'json',period,currency});if(period==='monthly')params.set('month',month);else if(period==='quarterly')params.set('quarter',quarter);else params.set('year',year);return `/api/admin/finance/reports?${params.toString()}`}
function reportCsvHref(period:string,month:string,quarter:string,year:string,currency:string){const params=new URLSearchParams({format:'csv',period,currency});if(period==='monthly')params.set('month',month);else if(period==='quarterly')params.set('quarter',quarter);else params.set('year',year);return `/api/admin/finance/reports?${params.toString()}`}
